// ============================================================================
// PARSE RESULTS NODE - IMPROVED URL & WHATSAPP EXTRACTION
// Updated: Feb 11, 2026
// Purpose: Extract ACTUAL business URLs and WhatsApp numbers correctly
// ============================================================================

const response = $input.first().json;
const items = [];

try {
  if (response.error) {
    const errorMsg = response.error.error_user_msg || response.error.message || 'Unknown API error';
    console.error('Facebook API Error:', errorMsg, 'Code:', response.error.code);
    return [{ 
      json: { 
        error: true, 
        errorMessage: errorMsg,
        errorCode: response.error.code,
        errorType: response.error.type
      } 
    }];
  }

  const ads = response.data || [];

  if (!Array.isArray(ads) || ads.length === 0) {
    console.log('No ads found for this search term');
    return [{ json: { noResults: true } }];
  }

  console.log(`Processing ${ads.length} ads from Facebook Ad Library API`);

  // ===== OBVIOUS IRRELEVANT CATEGORIES (MINIMAL FILTERING) =====
  const OBVIOUS_IRRELEVANT = /\b(watch|laikrodžiai|lithuania|tauras|mobile phone|smartphone|laptop|computer|electronics|gadget|food|restaurant|hotel|travel package|insurance|loan|père|kathy|novel|drama|story|fiction|book|game|gaming|astrology|horoscope|casino|betting)\b/gi;

  // ===== IMPROVED URL & WHATSAPP EXTRACTION FUNCTION =====
  function extractContactInfo(ad) {
    const contact = {
      business_website: null,
      whatsapp_url: null,
      whatsapp_number: null,
      instagram_url: null,
      facebook_url: null,
      phone_number: null,
      url_type: 'UNKNOWN'
    };

    // Combine ALL text fields for extraction
    const allText = [
      ad.page_name || '',
      ...(ad.ad_creative_bodies || []),
      ...(ad.ad_creative_link_captions || []),
      ...(ad.ad_creative_link_descriptions || []),
      ...(ad.ad_creative_link_titles || [])
    ].join(' ');

    // ===== EXTRACT WHATSAPP NUMBERS (PRIORITY 1) =====

    // Method 1: WhatsApp URLs (wa.me/919876543210)
    const waUrlMatch = allText.match(/(?:wa\.me\/|api\.whatsapp\.com\/send\?phone=)(\+?91)?([6-9]\d{9})/i);
    if (waUrlMatch) {
      const number = waUrlMatch[2]; // Just the 10-digit number
      contact.whatsapp_number = number;
      contact.whatsapp_url = `https://wa.me/91${number}`;
      console.log(`   ✅ WhatsApp URL found: ${contact.whatsapp_url}`);
    }

    // Method 2: Indian phone numbers in text (with optional +91 or 0)
    // Regex: Matches +919876543210, 919876543210, 09876543210, 9876543210
    if (!contact.whatsapp_number) {
      const phonePatterns = [
        /(?:\+91[-\s]?|91[-\s]?|0)?([6-9]\d{9})\b/g,  // Standard format
        /([6-9]\d{2})[-\s]?(\d{3})[-\s]?(\d{4})/g     // Formatted: 987-654-3210
      ];

      for (const pattern of phonePatterns) {
        const matches = allText.matchAll(pattern);
        for (const match of matches) {
          let number;
          if (match.length === 2) {
            // Standard match: group 1 is the 10-digit number
            number = match[1];
          } else if (match.length === 4) {
            // Formatted match: combine groups 1,2,3
            number = match[1] + match[2] + match[3];
          }

          // Validate it's exactly 10 digits starting with 6-9
          if (number && /^[6-9]\d{9}$/.test(number)) {
            contact.phone_number = number;
            contact.whatsapp_number = number;
            contact.whatsapp_url = `https://wa.me/91${number}`;
            console.log(`   ✅ Phone number found in text: ${number}`);
            break;
          }
        }
        if (contact.whatsapp_number) break;
      }
    }

    // ===== EXTRACT URLS (PRIORITY 2) =====

    const urlRegex = /(https?:\/\/[^\s<>"{}|\\^`\[\]]+)/gi;
    const foundUrls = allText.match(urlRegex) || [];

    for (const url of foundUrls) {
      const lowerUrl = url.toLowerCase();

      // Skip Facebook Ad Library URLs
      if (lowerUrl.includes('facebook.com/ads/archive')) {
        continue;
      }

      // ===== CATEGORIZE URLS CORRECTLY =====

      // Instagram (NOT a commercial website!)
      if (lowerUrl.includes('instagram.com/')) {
        // Extract Instagram handle from URL
        const handleMatch = url.match(/instagram\.com\/([a-zA-Z0-9._]+)/);
        if (handleMatch && handleMatch[1] && !handleMatch[1].includes('p/')) {
          contact.instagram_url = url;
          console.log(`   📸 Instagram: ${url}`);
        }
      }
      // Facebook Pages
      else if (lowerUrl.includes('facebook.com/')) {
        contact.facebook_url = url;
        console.log(`   📘 Facebook: ${url}`);
      }
      // WhatsApp URLs
      else if (lowerUrl.includes('wa.me') || lowerUrl.includes('whatsapp')) {
        contact.whatsapp_url = url;
        // Extract number from wa.me URL if not already extracted
        if (!contact.whatsapp_number) {
          const waNum = url.match(/wa\.me\/(?:\+?91)?([6-9]\d{9})/i);
          if (waNum) {
            contact.whatsapp_number = waNum[1];
          }
        }
        console.log(`   📱 WhatsApp URL: ${url}`);
      }
      // Commercial websites (ONLY non-social URLs)
      else if (!contact.business_website) {
        contact.business_website = url;
        console.log(`   💼 Business Website: ${url}`);
      }
    }

    // ===== EXTRACT DOMAIN FROM TEXT (e.g., "visit labelmonik.com") =====
    if (!contact.business_website) {
      const domainMatch = allText.match(/\b([a-z0-9-]+\.(com|in|co\.in|org|net))\b/i);
      if (domainMatch && domainMatch[1]) {
        // Exclude social media domains
        const domain = domainMatch[1].toLowerCase();
        if (!domain.includes('instagram') && !domain.includes('facebook') && !domain.includes('youtube')) {
          contact.business_website = `https://${domainMatch[1]}`;
          console.log(`   💼 Domain from text: ${contact.business_website}`);
        }
      }
    }

    // ===== FALLBACK: Facebook Page URL =====
    if (!contact.business_website && !contact.whatsapp_url && !contact.instagram_url && ad.page_id) {
      contact.facebook_url = `https://www.facebook.com/${ad.page_id}`;
      console.log(`   📘 Facebook Page (fallback): ${contact.facebook_url}`);
    }

    // ===== DETERMINE URL TYPE (PRIORITY ORDER) =====
    if (contact.business_website) {
      contact.url_type = 'WEBSITE';
    } else if (contact.whatsapp_url) {
      contact.url_type = 'WHATSAPP';
    } else if (contact.instagram_url) {
      contact.url_type = 'INSTAGRAM';
    } else if (contact.facebook_url) {
      contact.url_type = 'FACEBOOK_PAGE';
    }

    return contact;
  }

  // ===== PROCESS EACH AD =====
  for (const ad of ads) {
    if (!ad || typeof ad !== 'object' || !ad.id) {
      continue;
    }

    // MINIMAL FILTERING: Only reject OBVIOUS irrelevant
    const pageName = (ad.page_name || '').toLowerCase();

    if (OBVIOUS_IRRELEVANT.test(pageName)) {
      console.log(`❌ Excluded: "${ad.page_name}" - Obviously irrelevant category`);
      continue;
    }

    // Extract all contact info
    const contact = extractContactInfo(ad);

    // Determine primary landing URL
    let landingUrl = contact.business_website || 
                     contact.whatsapp_url || 
                     contact.instagram_url || 
                     contact.facebook_url || 
                     ad.ad_snapshot_url;

    console.log(`✅ Accepted: "${ad.page_name}"`);
    console.log(`   Type: ${contact.url_type}`);
    console.log(`   Website: ${contact.business_website || 'None'}`);
    console.log(`   WhatsApp: ${contact.whatsapp_number || 'None'}`);
    console.log(`   Instagram: ${contact.instagram_url || 'None'}`);

    items.push({
      json: {
        // Core identifiers
        page_id: ad.page_id || 'unknown',
        page_name: ad.page_name || 'Unknown Business',
        ad_id: ad.id || String(Date.now()),

        // Ad content
        ad_snapshot_url: ad.ad_snapshot_url || '',
        ad_creative_bodies: ad.ad_creative_bodies || [],

        // ===== CONTACT INFO (CORRECTED) =====
        ad_creative_link_url: landingUrl,
        business_website: contact.business_website,
        whatsapp_url: contact.whatsapp_url,
        whatsapp_number: contact.whatsapp_number,
        instagram_url: contact.instagram_url,
        facebook_url: contact.facebook_url,
        phone_number: contact.phone_number,
        url_type: contact.url_type,

        // Timing
        ad_delivery_start_time: ad.ad_delivery_start_time || null,
        ad_delivery_stop_time: ad.ad_delivery_stop_time || null,

        // Additional data
        currency: ad.currency || 'INR',
        spend: ad.spend || null,
        scraped_at: new Date().toISOString(),

        // Filtering metadata
        filter_passed: true,
        search_term_used: $input.first().json.searchTerm || 'unknown'
      }
    });
  }

  if (items.length === 0) {
    console.log('⚠️ All ads filtered out - no relevant businesses found');
    return [{ json: { noResults: true, reason: 'All ads filtered as irrelevant' } }];
  }

  console.log(`✅ Successfully processed ${items.length} relevant ads (filtered from ${ads.length} total)`);
  return items;

} catch (error) {
  console.error('Parse error:', error.message, error.stack);
  return [{ 
    json: { 
      error: true, 
      errorMessage: `Parse error: ${error.message}`,
      errorStack: error.stack
    } 
  }];
}

const ads = $input.all();
const pageMap = new Map();

for (const item of ads) {
  const ad = item.json;
  const pid = ad.page_id;

  if (!pid || pid === 'unknown') continue;

  if (!pageMap.has(pid)) {
    pageMap.set(pid, {
      page_id: pid,
      page_name: ad.page_name,
      ad_count: 0,
      sample_ad: ad,
      earliest_start: ad.ad_delivery_start_time,
      all_bodies: [],

      // ===== IMPROVED: Collect all URLs =====
      business_website: ad.business_website,
      whatsapp_url: ad.whatsapp_url,
      instagram_url: ad.instagram_url,
      facebook_url: ad.facebook_url,
      phone_number: ad.phone_number,
      url_type: ad.url_type,
      landing_url: ad.business_website || ad.whatsapp_url || ad.instagram_url || ad.facebook_url
    });
  }

  const page = pageMap.get(pid);
  page.ad_count++;

  // Update URLs if better ones found
  if (ad.business_website && !page.business_website) {
    page.business_website = ad.business_website;
    page.landing_url = ad.business_website;
  }
  if (ad.whatsapp_url && !page.whatsapp_url) {
    page.whatsapp_url = ad.whatsapp_url;
  }

  if (ad.ad_delivery_start_time) {
    if (!page.earliest_start || ad.ad_delivery_start_time < page.earliest_start) {
      page.earliest_start = ad.ad_delivery_start_time;
    }
  }

  if (Array.isArray(ad.ad_creative_bodies)) {
    page.all_bodies.push(...ad.ad_creative_bodies);
  }
}

const output = [];
for (const [pid, page] of pageMap.entries()) {
  output.push({ json: page });
}

return output.length > 0 ? output : [{ json: { noPages: true } }];

// ============================================================================
// SCORE & FILTER NODE - MINIMAL FILTERING (SAVE EVERYTHING VALID)
// Updated: Feb 11, 2026
// Goal: Only reject OBVIOUS irrelevant content, save 90%+ of businesses
// ============================================================================

console.log('='.repeat(80));
console.log('🚀 SCORE & FILTER NODE STARTED');
console.log('='.repeat(80));

// ===== STEP 1: ACCESS SPLIT PAGES DATA (UPSTREAM NODE) =====
let splitPagesData = null;

try {
  // Method 1: Try $('Split Pages') - recommended n8n method
  const splitPagesItems = $('Split Pages').all();

  if (splitPagesItems && splitPagesItems.length > 0) {
    splitPagesData = splitPagesItems[0].json;
    console.log('✅ Accessed Split Pages data via $("Split Pages").all()');
  } else {
    console.error('❌ $("Split Pages").all() returned empty array');
  }
} catch(e) {
  console.error('❌ Error accessing Split Pages:', e.message);
}

// Fallback: Try alternative method
if (!splitPagesData) {
  try {
    splitPagesData = $node["Split Pages"].json[0];
    console.log('✅ Accessed Split Pages data via $node (fallback)');
  } catch(e) {
    console.error('❌ Fallback method also failed:', e.message);
  }
}

// CRITICAL: Verify we have data
if (!splitPagesData || !splitPagesData.page_name) {
  console.error('❌❌❌ CRITICAL ERROR: Cannot access Split Pages data');
  console.error('Available nodes:', Object.keys(this.getWorkflow().nodes));
  return [{ 
    json: { 
      filtered: true, 
      reason: 'ERROR: Split Pages data not accessible',
      debug_info: 'Check node connections and names'
    } 
  }];
}

// Extract all fields from Split Pages
const pd = {
  page_id: splitPagesData.page_id || 'unknown',
  page_name: splitPagesData.page_name || 'Unknown',
  ad_count: splitPagesData.ad_count || 1,
  all_bodies: splitPagesData.all_bodies || [],
  landing_url: splitPagesData.landing_url || '',
  business_website: splitPagesData.business_website || null,
  whatsapp_url: splitPagesData.whatsapp_url || null,
  instagram_url: splitPagesData.instagram_url || null,
  facebook_url: splitPagesData.facebook_url || null,
  phone_number: splitPagesData.phone_number || null,
  url_type: splitPagesData.url_type || 'UNKNOWN',
  sample_ad: splitPagesData.sample_ad || {},
  earliest_start: splitPagesData.earliest_start || null
};

console.log('📊 Split Pages Data Loaded:');
console.log(`   Page Name: "${pd.page_name}"`);
console.log(`   Page ID: ${pd.page_id}`);
console.log(`   Ad Count: ${pd.ad_count}`);
console.log(`   URL Type: ${pd.url_type}`);
console.log(`   Business Website: ${pd.business_website || 'None'}`);
console.log(`   WhatsApp URL: ${pd.whatsapp_url || 'None'}`);
console.log(`   Instagram URL: ${pd.instagram_url || 'None'}`);
console.log(`   Landing URL: ${pd.landing_url || 'None'}`);

// ===== STEP 2: GET HTML FROM FETCH LANDING PAGE (DIRECTLY CONNECTED) =====
let html = '';
let htmlFetchError = false;

try {
  const fetchPageItems = $input.all();

  if (fetchPageItems && fetchPageItems.length > 0) {
    const fetchPageData = fetchPageItems[0];

    // Check if fetch failed (continueOnFail = true)
    if (fetchPageData.json && fetchPageData.json.error) {
      htmlFetchError = true;
      console.warn(`⚠️  Fetch Landing Page failed: ${fetchPageData.json.error.message || 'Unknown error'}`);
    } else {
      // Try multiple methods to extract HTML
      if (fetchPageData.binary && fetchPageData.binary.data && fetchPageData.binary.data.data) {
        html = Buffer.from(fetchPageData.binary.data.data, 'base64').toString('utf-8');
        console.log(`✅ HTML extracted from binary: ${html.length} chars`);
      } else if (fetchPageData.json && fetchPageData.json.data) {
        html = String(fetchPageData.json.data);
        console.log(`✅ HTML extracted from json.data: ${html.length} chars`);
      } else if (typeof fetchPageData.json === 'string') {
        html = fetchPageData.json;
        console.log(`✅ HTML extracted from json string: ${html.length} chars`);
      } else {
        console.warn(`⚠️  No HTML data found in Fetch Landing Page response`);
      }
    }
  } else {
    console.warn(`⚠️  No Fetch Landing Page data (likely skipped for ${pd.url_type})`);
  }
} catch(e) {
  console.error(`❌ Error extracting HTML: ${e.message}`);
}

// ===== STEP 3: COMBINE ALL TEXT FOR ANALYSIS =====
function join(arr) {
  return Array.isArray(arr) ? arr.filter(x => x && typeof x === 'string').join(' ') : '';
}

const pageName = pd.page_name || '';
const allBodies = join(pd.all_bodies);
const allText = [pageName, allBodies, html].join(' ');

console.log('📝 Text Analysis:');
console.log(`   Page Name: ${pageName.length} chars`);
console.log(`   Ad Bodies: ${allBodies.length} chars`);
console.log(`   HTML: ${html.length} chars`);
console.log(`   Total Text: ${allText.length} chars`);

// ===== STEP 4: MINIMAL FILTERING - ONLY REJECT OBVIOUS NON-CLOTHING BUSINESSES =====

// ❌ REJECT 1: Obvious irrelevant categories (watches, electronics, etc.)
const OBVIOUS_IRRELEVANT = /\b(watch|laikrodžiai|lithuania|tauras|mobile phone|smartphone|laptop|computer|electronics|gadget|food|restaurant|hotel|travel package|insurance|loan|père|kathy|novel|drama|story|fiction|book|game|gaming|astrology|horoscope|casino|betting)\b/gi;

const pageNameLower = pageName.toLowerCase();
const isObviouslyIrrelevant = OBVIOUS_IRRELEVANT.test(pageNameLower);

if (isObviouslyIrrelevant) {
  console.log(`❌ REJECTED: "${pd.page_name}" - Obviously irrelevant category (not fashion/clothing)`);
  return [{ 
    json: { 
      filtered: true, 
      reason: `Irrelevant category detected in page name: ${pageNameLower}` 
    } 
  }];
}

// ✅ ACCEPT: Everything else (fashion, clothing, lifestyle brands, etc.)
console.log(`✅ PASSED MINIMAL FILTER: "${pd.page_name}"`);

// ===== STEP 5: DETECT QUALITY SIGNALS =====

// WhatsApp detection
const WA_NUMBER = /\b[6-9]\d{9}\b/g;
const WA_KEYWORD = /whatsapp|wa\.me|click\.to\.whatsapp/gi;
const hasWANumber = WA_NUMBER.test(allText);
const hasWAKeyword = WA_KEYWORD.test(allText) || !!pd.whatsapp_url;
const hasWhatsApp = hasWANumber || hasWAKeyword || !!pd.phone_number;

// Pricing signals
const PRICE_SPECIFIC = /(rs\.?|₹)\s*\d+|price[:\s]*\d+/gi;
const PRICE_DM = /dm\s*(for|to\s*get)?\s*price|comment\s*(for|to\s*get)?\s*(price|detail|link)|whatsapp\s*for\s*price|message\s*for\s*price/gi;
const hasSpecificPrice = PRICE_SPECIFIC.test(allText);
const hasDMPrice = PRICE_DM.test(allText);
const hasPricing = hasSpecificPrice || hasDMPrice;

// Website detection
const hasCommercialWebsite = !!pd.business_website;

// Location detection
const LOCATION = /\b(jaipur|delhi|mumbai|surat|ahmedabad|bangalore|bengaluru|hyderabad|chennai|kolkata|pune|lucknow|kanpur|nagpur|indore|bhopal|chandigarh)\b/gi;
const JAIPUR = /\b(jaipur|pink city)\b/gi;
const hasLocation = LOCATION.test(allText);
const hasJaipur = JAIPUR.test(allText);

// Pixel detection (only if HTML was fetched)
const PIXEL = /(fbq\(|fbevents)/gi;
const hasPixel = html.length > 0 ? PIXEL.test(html) : false;

// Social media
const hasInstagram = !!pd.instagram_url;
const hasFacebookPage = !!pd.facebook_url;

console.log('🔍 Quality Signals Detected:');
console.log(`   WhatsApp: ${hasWhatsApp}`);
console.log(`   Commercial Website: ${hasCommercialWebsite}`);
console.log(`   Pricing Info: ${hasPricing}`);
console.log(`   Location Mentioned: ${hasLocation}`);
console.log(`   Jaipur Local: ${hasJaipur}`);
console.log(`   Facebook Pixel: ${hasPixel}`);
console.log(`   Instagram: ${hasInstagram}`);
console.log(`   Facebook Page: ${hasFacebookPage}`);

// ===== STEP 6: TIERING & PRIORITIZATION =====

const cnt = pd.ad_count;
let tier = '';
let priority = 'LOW';
let reason = '';

// TIER 1 - HIGH PRIORITY
if (hasWhatsApp && hasCommercialWebsite) {
  tier = 'TIER_1';
  priority = 'HIGH';
  reason = 'WhatsApp + Commercial Website';
} else if (hasWhatsApp && hasPricing) {
  tier = 'TIER_1';
  priority = 'HIGH';
  reason = 'WhatsApp + Pricing Info';
} else if (hasWhatsApp && cnt >= 2) {
  tier = 'TIER_1';
  priority = 'HIGH';
  reason = 'WhatsApp + Multiple Ads';
} else if (hasCommercialWebsite && hasPricing) {
  tier = 'TIER_1';
  priority = 'HIGH';
  reason = 'Website + Pricing Info';
}
// TIER 1 - MEDIUM PRIORITY
else if (hasCommercialWebsite) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'Has Commercial Website';
} else if (hasWhatsApp) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'Has WhatsApp Contact';
} else if (hasDMPrice) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'DM for Price (Potential WhatsApp)';
} else if (hasLocation && cnt >= 2) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'Physical Location + Multiple Ads';
} else if (cnt >= 3) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'Running 3+ Ads (Active Marketer)';
}
// TIER 2 - LOW PRIORITY
else if (hasInstagram && hasPricing) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Instagram + Pricing';
} else if (hasInstagram && cnt >= 2) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Instagram + Multiple Ads';
} else if (hasPricing) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Shows Pricing Info';
} else if (cnt >= 2) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Running 2+ Ads';
} else if (hasFacebookPage) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Active Facebook Page';
}
// TIER 3 - ACCEPT BUT LOWEST PRIORITY
else {
  tier = 'TIER_3';
  priority = 'LOWEST';
  reason = 'Single Ad, Minimal Signals (Review Manually)';
}

// ===== STEP 7: SCORING =====
let vol = 0;
if (cnt >= 50) vol = 30;
else if (cnt >= 25) vol = 25;
else if (cnt >= 12) vol = 20;
else if (cnt >= 6) vol = 15;
else if (cnt >= 3) vol = 10;
else if (cnt >= 2) vol = 5;
else vol = 2; // Even single ad gets some points

const len = allBodies.length;
let soph = 0;
if (len > 500) soph += 8;
else if (len > 200) soph += 5;
else if (len > 100) soph += 3;
else if (len > 50) soph += 1;

const variationCount = (pd.all_bodies || []).length;
if (variationCount >= 5) soph += 8;
else if (variationCount >= 3) soph += 5;
else if (variationCount >= 2) soph += 2;

if (html.length > 0 && html.includes('<img')) soph += 6;
soph = Math.min(soph, 22);

let long = 0;
if (pd.earliest_start) {
  try {
    const d = Math.floor((new Date() - new Date(pd.earliest_start)) / 86400000);
    if (d >= 90) long = 15;
    else if (d >= 60) long = 12;
    else if (d >= 30) long = 10;
    else if (d >= 14) long = 7;
    else if (d >= 7) long = 5;
    else if (d >= 3) long = 2;
  } catch(e) {}
}

const track = hasPixel ? 8 : 0;
const loc = hasJaipur ? 10 : 0;
const wa = hasWhatsApp ? 10 : 0;
const tot = vol + soph + long + track + loc + wa;

// ===== STEP 8: INQUIRY ESTIMATION =====
let inquiryEstimate = 'N/A';

if (hasWhatsApp) {
  if (cnt >= 6 && (hasCommercialWebsite || hasPixel)) {
    inquiryEstimate = '30-50+ inquiries/day';
  } else if (cnt >= 3) {
    inquiryEstimate = '15-30 inquiries/day';
  } else {
    inquiryEstimate = '5-15 inquiries/day';
  }
} else if (hasCommercialWebsite) {
  inquiryEstimate = '3-10 inquiries/day';
} else if (hasInstagram) {
  if (hasPricing) {
    inquiryEstimate = '2-5 inquiries/day';
  } else {
    inquiryEstimate = '<2 inquiries/day';
  }
} else {
  inquiryEstimate = 'Unknown - needs contact method';
}

// ===== STEP 9: OUTPUT =====
